function questTracker(c){let main=c.quest==='accepted'?'Principal: derrotá al grupo de bandidos en las Afueras.':c.quest==='done'?'Principal: regresá con el Maestro.':c.quest==='none'?'Principal disponible: hablá con el Maestro.':'Sin misión principal.';let sq={none:'Secundaria: hablá con el Herrero de Arca.',deliverShield:'Secundaria: entregá el escudo al Guardia de la Puerta Oeste.',hunt:'Secundaria: conseguí 5 Pieles y 3 Colmillos de jabalí.',huntReady:'Secundaria: volvé con el Guardia Oeste.',craftCollar:'Secundaria: fabricá el Collar de Jabalí con el Joyero.',returnCollar:'Secundaria: llevá el Collar de Jabalí al Guardia.',craftArmor:'Secundaria: fabricá la Armadura de Cuero de Jabalí en Textil.',returnArmor:'Secundaria: llevá la Armadura al Guardia.',complete:'Cadena del Guardia Oeste completada.'}[side(c)];return `<details class="quest-track explore-objectives"><summary>📜 Objetivos</summary><div><b>${main}</b><br><span>🧭 ${sq}</span></div></details>`}
function enterInterior(where){let c=hero();c.location=where;c.worldPos[where]={x:360,y:430};save();world()}
