function merchantName(map){return {smith:'⚒️ Herrero de Arca',jeweler:'💎 Joyero de Arca',textile:'🧵 Telas y Cuero',itemshop:'🧪 Tienda de artículos'}[map]||'Comerciante'}
function merchantMenu(map){closeModal();let c=hero(),q=side(c),mission=map==='smith'&&q==='none'?'<button id="smithQuest">📜 Encargo: llevar un escudo</button>':'';let canCraft=(map==='jeweler'&&(q==='craftCollar'||c.recipes?.collar||q==='complete'))||(map==='textile'&&(q==='craftArmor'||c.recipes?.armor||q==='complete'));modal(`<h3>${merchantName(map)}</h3><p>¿Qué necesitás?</p>${mission}<div class="actions shop-actions"><button id="shopBuy">🛒 Comprar</button><button id="shopSell">💰 Vender</button>${canCraft?'<button id="shopCraft">🔨 Fabricar</button>':''}<button class="secondary" id="shopExit">Salir</button></div>`,false);$('#smithQuest')?.addEventListener('click',()=>{if(c.inventory.length>=12)return toast('Necesitás espacio en la mochila.');c.inventory.push('Escudo del Guardia');c.sideQuest='deliverShield';save();closeModal();toast('Recibiste el Escudo del Guardia.');world()});$('#shopBuy').onclick=()=>buyMenu(map);$('#shopSell').onclick=()=>sellMenu(map);$('#shopCraft')?.addEventListener('click',()=>craftMenu(map));$('#shopExit').onclick=()=>{closeModal();world()}}
function smithDialog(){merchantMenu('smith')}function jewelerDialog(){merchantMenu('jeweler')}function textileDialog(){merchantMenu('textile')}function itemShopDialog(){merchantMenu('itemshop')}
function shopStock(map){return {smith:[['Espada de Hierro',15],['Escudo de Madera',15]],jeweler:[['Anillo Simple',20]],textile:[['Botas de Cuero',10],['Casco de Cuero',10],['Guantes de Cuero',10]],itemshop:[['Poción de Vida Básica',3],['Antídoto',2],['Vendas',2]]}[map]||[]}
function buyMenu(map){closeModal();let c=hero(),stock=shopStock(map);function draw(){let rows=stock.map(([n,p])=>`<button class="sell-row" data-buy="${esc(n)}" data-price="${p}">${esc(n)} <small>${itemData[n]?.effect||''}</small> <b>🪙${p}</b></button>`).join('');let m=$('#modal .card');m.innerHTML=`<h3>🛒 Comprar · ${merchantName(map)}</h3><p>🪙 Oro: <b>${c.gold}</b> · Mochila: <b>${c.inventory.length}/12</b></p>${rows||'<p>Sin artículos disponibles.</p>'}<div class="actions"><button class="secondary" id="shopBack">Volver</button></div>`;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let n=b.dataset.buy,p=+b.dataset.price;if(c.gold<p)return toast('No tenés suficiente oro.');if(c.inventory.length>=12)return toast('La mochila está llena.');c.gold-=p;c.inventory.push(n);save();toast(`${n} comprado.`);draw()});$('#shopBack').onclick=()=>merchantMenu(map)}modal('<div></div>',false);draw()}
function sellMenu(map){closeModal();let c=hero(),selected=new Set();function draw(){let rows=c.inventory.map((n,i)=>{let d=itemData[n]||{sell:0};return d.sell?`<button class="sell-row ${selected.has(i)?'selected-sale':''}" data-sell="${i}">${selected.has(i)?'☑️':'⬜'} ${esc(n)} <b>+🪙${d.sell}</b></button>`:''}).join('');let total=[...selected].reduce((a,i)=>a+(itemData[c.inventory[i]]?.sell||0),0);let m=$('#modal .card');m.innerHTML=`<h3>💰 Vender · ${merchantName(map)}</h3><p>🪙 Oro: <b>${c.gold}</b></p>${rows||'<p>No tenés objetos vendibles.</p>'}<p><b>${selected.size}</b> seleccionados · recibirás <b>🪙${total}</b></p><div class="actions"><button id="sellSelected" ${selected.size?'':'disabled'}>Vender seleccionados</button><button class="secondary" id="shopBack">Volver</button></div>`;document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{let i=+b.dataset.sell;selected.has(i)?selected.delete(i):selected.add(i);draw()});$('#shopBack').onclick=()=>merchantMenu(map);$('#sellSelected').onclick=()=>{let idx=[...selected].sort((a,b)=>b-a),total=0,names=[];for(let i of idx){let n=c.inventory[i],v=itemData[n]?.sell||0;if(v){total+=v;names.push(n);c.inventory.splice(i,1)}}c.gold+=total;selected.clear();save();toast(`${names.length} objeto${names.length!==1?'s':''} vendidos por ${total} oro.`);draw()}}modal('<div></div>',false);draw()}
function craftMenu(map){closeModal();let c=hero(),q=side(c),recipes=[];if(map==='jeweler'&&(q==='craftCollar'||c.recipes?.collar||q==='complete'))recipes.push(['Collar de Jabalí','Colmillo de jabalí',3,3,'returnCollar']);if(map==='textile'&&(q==='craftArmor'||c.recipes?.armor||q==='complete'))recipes.push(['Armadura de cuero de jabalí','Piel de jabalí',5,3,'returnArmor']);let rows=recipes.map((r,i)=>`<button class="sell-row" data-craft="${i}">${r[0]} <small>${r[2]} × ${r[1]}</small> <b>🪙${r[3]}</b></button>`).join('');modal(`<h3>🔨 Fabricar · ${merchantName(map)}</h3>${rows||'<p>No hay recetas disponibles.</p>'}<div class="actions"><button class="secondary" id="shopBack">Volver</button></div>`,false);document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{let r=recipes[+b.dataset.craft];craftItem(...r,map)});$('#shopBack').onclick=()=>merchantMenu(map)}
function craftItem(result,mat,qty,cost,next,map){let c=hero();if(countItem(c,mat)<qty)return toast(`Faltan materiales: ${qty} × ${mat}.`);if(c.gold<cost)return toast(`Necesitás ${cost} de oro.`);let after=c.inventory.length-qty+1;if(after>12)return toast('Necesitás espacio en la mochila.');removeItems(c,mat,qty);c.gold-=cost;addItem(c,result);if(side(c)==='craftCollar'&&result==='Collar de Jabalí')c.sideQuest='returnCollar';if(side(c)==='craftArmor'&&result==='Armadura de cuero de jabalí')c.sideQuest='returnArmor';save();toast(`${result} fabricado.`);craftMenu(map)}
function useConsumable(i,name,use){let c=hero();if(use==='heal'){if(c.hp>=maxHp(c))return toast('Ya tenés la Vida completa.');c.hp=Math.min(maxHp(c),c.hp+3)}else if(use==='antidote')return toast('Fuera de combate no tenés Veneno activo.');else if(use==='bandage')return toast('Fuera de combate no tenés Herida activa.');c.inventory.splice(i,1);save();closeModal();inventory();toast(`${name} utilizado.`)}
