function startBoarPatrol(){let phase=0;patrolTimer=setInterval(()=>{if(hero()?.location!=='west')return clearInterval(patrolTimer);phase++;document.querySelectorAll('.boar-patrol').forEach(el=>{let i=+el.dataset.boar,base=mapData.west.boars[i],dx=((phase+i)%8<4?1:-1)*18,dy=i?Math.sin(phase)*12:Math.cos(phase)*12;el.style.left=(base.x+dx)+'px';el.style.top=(base.y+dy)+'px'})},700)}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function blocked(map,x,y){let d=mapData[map],r=24;if(x<r||y<r||x>d.w-r||y>d.h-r)return true;if(map==='west'){let cell=d.cell,cx=Math.floor(x/cell),cy=Math.floor(y/cell);if(westBlockedCell(cx,cy))return true;}return d.obstacles.some(o=>x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)}
function worldTap(e,map){let r=e.currentTarget.getBoundingClientRect(),d=mapData[map],x=(e.clientX-r.left)*d.w/r.width,y=(e.clientY-r.top)*d.h/r.height;moveWorld(map,{x,y})}
function worldZoomValue(c=hero()){return clamp(Number(c?.exploreZoom)||0.72,0.42,1.15)}
