function combatPortrait(u){if(u?.type==='hero')return 'assets-miniaturas/guerrero-humano-abajo.png';let src=enemySprite(u);return src||''}
function combatStates(u){let a=[];if(u?.wound>0)a.push(`🩸 Herida ×${u.wound}`);if(u?.poison>0)a.push(`☠️ Veneno ×${u.poison}`);if(u?.burn>0)a.push(`🔥 Quemadura ×${u.burn}`);if(u?.type==='hero'&&furyBonus(hero(),u.hp)>0)a.push(`🔥 Furia +${furyBonus(hero(),u.hp)}`);return a.length?a.join(' · '):'Sin estados'}
function renderDeployment(){let tiles='';for(let y=0;y<10;y++)for(let x=0;x<10;x++){let k=`${x},${y}`,z=occupied(x,y),valid=B.deployTiles.includes(k)&&!obs.has(k)&&!z,chosen=B.deployPos===k,classes=['tile'];if(obs.has(k))classes.push('obstacle',obstacleClass(k));if(valid)classes.push('deploy');if(chosen)classes.push('deploy-chosen');tiles+=`<div class="${classes.join(' ')}" data-x="${x}" data-y="${y}">${z?`<div class="unit-piece"><div class="unit-vitals">${z.hp}/${z.max}</div><div class="unit-hp"><i style="width:${Math.max(0,Math.min(100,z.hp/z.max*100))}%"></i></div><span class="unit-icon">${unitVisual(z)}</span></div>`:chosen?`<div class="deploy-hero"><img class="hero-sprite" src="assets-miniaturas/guerrero-humano-abajo.png" alt=""></div>`:''}</div>`}app.innerHTML=`<section class="screen"><div class="topbar"><b>Despliegue inicial</b><span>Antes de la Ronda 1</span></div><div class="card"><b>Elegí dónde iniciar</b><p class="small">Tocá una de las posiciones resaltadas. Algunas están juntas y otras separadas. La iniciativa y el temporizador comenzarán recién cuando confirmes.</p></div><div class="battle-grid visual-battle${battleBoardAttrs().cls}" id="battleGrid"${battleBoardAttrs().style}>${tiles}</div><div class="actions deployment-actions"><button id="confirmDeploy" ${B.deployPos?'':'disabled'}>Confirmar posición</button><button class="secondary" id="cancelBattle">Cancelar combate</button></div></section>`;$('#battleGrid').onclick=e=>{let t=e.target.closest('.tile');if(!t)return;let k=`${t.dataset.x},${t.dataset.y}`;if(!B.deployTiles.includes(k)||obs.has(k)||occupied(+t.dataset.x,+t.dataset.y))return;B.deployPos=k;renderDeployment()};$('#confirmDeploy').onclick=()=>{let [x,y]=B.deployPos.split(',').map(Number),h=getU('hero');h.x=x;h.y=y;B.deployment=false;B.deployPos=null;beginTurn()};$('#cancelBattle').onclick=()=>{B=null;world()}}
function cur(){return B.units.find(u=>u.id===B.order[B.turn])}function getU(id){return B.units.find(u=>u.id===id)}function occupied(x,y){return B.units.find(u=>u.x===x&&u.y===y)}function aliveOccupied(x,y){return B.units.find(u=>u.alive&&u.x===x&&u.y===y)}function corpseAt(x,y){return B.units.find(u=>!u.alive&&u.x===x&&u.y===y)}function free(x,y){return x>=0&&y>=0&&x<10&&y<10&&!obs.has(`${x},${y}`)&&!occupied(x,y)}function md(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}function adj8(a,b){return Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y))===1}
function beginTurn(){clearInterval(B.timerId);while(!cur()?.alive){B.turn++;if(B.turn>=B.order.length){B.turn=0;B.round++} }let u=cur();u.pa=u.maxPa;u.pm=u.maxPm;u.shield=0;u.uses={};for(let k in u.cd)if(u.cd[k]>0)u.cd[k]--;if(u.type==='hero'&&t(hero(),'guard'))u.shield+=2;if(u.type==='hero'&&hero().equipment.amulet==='Collar de Jabalí')u.shield+=1;if(u.type==='hero'&&hero().equipment.offhand==='Escudo de Madera')u.shield+=1;tickStates(u);if(!u.alive){nextTurn();return}B.timer=30;B.selectedAction=null;B.skillsOpen=false;B.selectedUnitId=u.id;renderBattle();B.timerId=setInterval(()=>{B.timer--;let el=$('#timer');if(el)el.textContent=B.timer+'s';if(B.timer<=0)nextTurn()},1000);if(u.type!=='hero')setTimeout(enemyAI,550)}
function tickStates(u){if(u.wound>0){damage(u,u.wound,false);if(u.type==='hero'&&u.alive){let r=woundRes(hero());if(r)u.wound=Math.max(0,u.wound-r)}}if(u.poison>0&&u.alive)damage(u,u.poison,false);if(u.burn>0&&u.alive)damage(u,u.burn,false)}function nextTurn(){clearInterval(B.timerId);if(checkBattleEnd())return;B.turn++;if(B.turn>=B.order.length){B.turn=0;B.round++}beginTurn()}
function actionInfo(a){let c=hero(),h=getU('hero'),d=baseDamage(c,h?.hp??c.hp);return({move:['Mover','Cada casilla recorrida consume 1 PM. Movimiento ortogonal.','1 PM/casilla','Casilla libre','Hasta PM disponibles','—','—'],normal:['Ataque Normal',`Inflige ${d} de daño con el arma equipada.`,'1 PA','1 enemigo','Adyacente (8 casillas)','Sin límite','Sin CD'],power:['Golpe Potenciado',`A.N. +2 (${d+2} daño actual) y Ruptura de Escudo 3.`,'2 PA','1 enemigo','Adyacente','1/turno','CD 1'],cut:['Corte',`Inflige A.N. (${d} actual) y aplica Herida.`,'2 PA','1 enemigo','Adyacente','2/turno','CD 1'],block:['Bloqueo','Obtiene +3 Escudo.','1 PA','Propio personaje','Personal','2/turno','Sin CD'],movebody:['Mover cuerpo','Levanta un cadáver adyacente por 1 PA. Mientras lo cargás, moverte cuesta 2 PM por casilla y no podés atacar. Soltarlo es gratis en una casilla libre adyacente.','1 PA al levantar','Cadáver / casilla libre','Adyacente','Sin límite','Sin CD']})[a]}
function infoPanel(a){let z=actionInfo(a);if(!z)return'';return `<div class="action-info"><div><b>${z[0]}</b><span>${z[2]}</span></div><p>${z[1]}</p><div class="info-grid"><span>🎯 ${z[3]}</span><span>📏 ${z[4]}</span><span>🔁 ${z[5]}</span><span>⏳ ${z[6]}</span></div></div>`}
function unitStateIcons(z){let a=[];if(z.wound>0)a.push(`<span title="Herida ${z.wound}">🩸×${z.wound}</span>`);if(z.poison>0)a.push(`<span title="Veneno ${z.poison}">☠️×${z.poison}</span>`);if(z.burn>0)a.push(`<span title="Quemadura ${z.burn}">🔥×${z.burn}</span>`);if(z.type==='hero'&&furyBonus(hero(),z.hp)>0)a.push(`<span title="Furia +${furyBonus(hero(),z.hp)} Daño">🔥</span>`);return a.length?`<div class="unit-states">${a.join('')}</div>`:''}
function enemyAttack(u){return u.type==='dagger'?3:u.type==='boar'||u.type==='cross'?2:0}
function renderBattle(){let u=cur(),view=getU(B.selectedUnitId)||u;if(!view?.alive)view=u;let tiles='';let moves=u.type==='hero'&&B.selectedAction==='move'?reachable(u,B.carryingBody?Math.floor(u.pm/2):u.pm):new Set();for(let y=0;y<10;y++)for(let x=0;x<10;x++){let z=occupied(x,y),classes=['tile'],k=`${x},${y}`;if(obs.has(k))classes.push('obstacle',obstacleClass(k));if(moves.has(k))classes.push('move');if(z?.id===B.selectedUnitId&&z.alive)classes.push('inspected');if(z?.id===u.id&&z.alive)classes.push('turn-unit');if(z&&!z.alive)classes.push('corpse-tile');if(u.type==='hero'&&B.selectedAction&&!['move','block'].includes(B.selectedAction)&&validTargetTile(x,y,B.selectedAction))classes.push('target');if(B.fx?.attacker===k)classes.push('fx-attacker');if(B.fx?.target===k)classes.push('fx-target');if(B.fx?.cells?.includes(k))classes.push(B.fx.kind==='poison'?'fx-poison':'fx-projectile');tiles+=`<div class="${classes.join(' ')}" data-x="${x}" data-y="${y}">${z?`<div class="unit-piece ${z.alive?'':'corpse'}">${z.alive?unitStateIcons(z):''}${z.alive?`<div class="unit-vitals">${z.hp}/${z.max}</div>`:''}<div class="unit-hp"><i style="width:${Math.max(0,Math.min(100,z.hp/z.max*100))}%"></i></div><span class="unit-icon">${z.alive?unitVisual(z):'☠️'}</span>${z.alive?'':'<span class="unit-badge">KO</span>'}${B.fx?.floatAt===k?`<span class="damage-float">${B.fx.floatText}</span>`:''}</div>`:''}${B.fx?.projectileAt===k?`<span class="battle-projectile">${B.fx.projectile||'✦'}</span>`:''}</div>`}
let order=B.order.map(id=>{let z=getU(id);return`<span class="turn-chip ${z.id===u.id?'current':''}" style="opacity:${z.alive?1:.35}">${z.alive?z.icon:'☠️'} ${z.ini}</span>`}).join('');
let bodyButton=(B.carryingBody||B.units.some(z=>!z.alive))?`<button data-act="movebody">☠️<b>${B.carryingBody?'Soltar':'Cuerpo'}</b></button>`:'';
let skills=`${hero().activeAbilities?.includes('cut')?'<button data-act="cut">🩸<b>Corte</b><small>2 PA</small></button>':''}${hero().activeAbilities?.includes('power')?'<button data-act="power">💥<b>G. Potenciado</b><small>2 PA</small></button>':''}${hero().activeAbilities?.includes('block')?'<button data-act="block">🛡️<b>Bloqueo</b><small>1 PA</small></button>':''}${bodyButton}`;
let logText=B.log.slice(-5).join('<br>')||'Comienza el combate.';
app.innerHTML=`<section class="screen combat-screen"><div class="combat-head"><div><b>Ronda ${B.round} · ${u.icon} ${esc(u.name)}</b><div class="turn-order compact-order">${order}</div></div><span class="combat-timer">⏱️ <b id="timer">${B.timer}s</b></span></div>${B.notice?`<div class="enemy-action-banner">${B.notice}</div>`:''}<div class="test-panel combat-test compact-test"><b>🧪 PRUEBAS</b><button id="testFinish">☠ Terminar combate</button></div><div class="battle-grid visual-battle${battleBoardAttrs().cls} ${battleAnimating?'animating':''}" id="battleGrid"${battleBoardAttrs().style}>${tiles}</div><div class="fighter-panel fighter-panel-new"><div class="fighter-avatar fighter-avatar-new"><img src="${combatPortrait(view)}" alt=""></div><div class="fighter-main"><div class="fighter-name"><b>${esc(view.name)}</b><small>${view.type==='hero'?`Guerrero · Nv.${hero().level}`:'Enemigo'}</small></div><div class="fighter-vitals"><span>❤️ <b>${view.hp}/${view.max}</b></span><span>🛡️ <b>${view.shield}</b></span>${view.type!=='hero'?`<span>⚔️ <b>${enemyAttack(view)}</b></span><span>⚡ Ini <b>${view.ini}</b></span>`:''}<span>PA <b>${view.pa}/${view.maxPa}</b></span><span>PM <b>${view.pm}/${view.maxPm}</b></span></div><div class="fighter-states">${combatStates(view)}</div></div></div>${u.type==='hero'?`<div class="combat-ui combat-ui-new"><div class="main-actions"><button data-act="move" class="${B.selectedAction==='move'?'active-action':''}">👣<b>Mover</b></button><button data-act="normal" class="${B.selectedAction==='normal'?'active-action':''}">⚔️<b>Ataque</b></button><button id="toggleSkills" class="${B.skillsOpen?'active-action':''}">✨<b>Habilidades</b></button><button id="battleItems">🎒<b>Objeto</b></button><button class="end-turn" id="end">⏭️<b>Fin turno</b></button></div>${B.skillsOpen?`<div class="skill-drawer">${skills}</div>`:''}${B.selectedAction?infoPanel(B.selectedAction):''}<p class="small combat-help">${B.selectedAction?(B.carryingBody&&B.selectedAction==='movebody'?'Elegí una casilla libre adyacente para soltar el cuerpo.':'Elegí una casilla u objetivo válido.'):'Tocá un combatiente para inspeccionarlo o elegí una acción.'}</p></div>`:''}<button class="combat-log-toggle" id="toggleLog">📜 Registro ${B.logOpen?'▲':'▼'}</button>${B.logOpen?`<div class="card small combat-log">${logText}</div>`:''}</section>`;
$('#battleGrid').onclick=battleTap;document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{let a=b.dataset.act;B.bodyTarget=null;if(B.selectedAction===a){B.selectedAction=null;B.skillsOpen=false;renderBattle();return}if(B.carryingBody&&['normal','power','cut'].includes(a))return toast('No podés atacar mientras transportás un cuerpo.');B.skillsOpen=['cut','power','block','movebody'].includes(a);B.selectedAction=a;renderBattle()});$('#toggleSkills')?.addEventListener('click',()=>{B.skillsOpen=!B.skillsOpen;if(B.skillsOpen)B.selectedAction=null;renderBattle()});$('#end')?.addEventListener('click',nextTurn);$('#battleItems')?.addEventListener('click',battleItems);$('#testFinish')?.addEventListener('click',testFinishCombat);$('#toggleLog')?.addEventListener('click',()=>{B.logOpen=!B.logOpen;renderBattle()})}

function actionName(a){return({move:'Mover',normal:'Ataque Normal',power:'Golpe Potenciado',cut:'Corte'})[a]||a}function reachable(u,pm){let seen=new Map([[`${u.x},${u.y}`,0]]),q=[[u.x,u.y]];while(q.length){let [x,y]=q.shift(),d=seen.get(`${x},${y}`);if(d>=pm)continue;for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(free(nx,ny)&&!seen.has(k)){seen.set(k,d+1);q.push([nx,ny])}}}seen.delete(`${u.x},${u.y}`);return new Set(seen.keys())}
function validTargetTile(x,y,a){let h=getU('hero'),z=occupied(x,y);if(a==='movebody'){if(B.carryingBody)return !z&&free(x,y)&&adj8(h,{x,y});if(h.pa<1)return false;return z&&!z.alive&&adj8(h,z)}if(B.carryingBody&&['normal','power','cut'].includes(a))return false;return z&&z.type!=='hero'&&z.alive&&adj8(h,z)&&((a==='normal'&&h.pa>=1)||(a==='power'&&h.pa>=2&&(h.uses.power||0)<1)||(a==='cut'&&h.pa>=2&&(h.uses.cut||0)<2))}
function sleep(ms){return new Promise(r=>setTimeout(r,ms))}function lineCells(a,b){let out=[];if(a.x===b.x){let d=Math.sign(b.y-a.y);for(let y=a.y+d;y!==b.y;y+=d)out.push(`${a.x},${y}`)}else if(a.y===b.y){let d=Math.sign(b.x-a.x);for(let x=a.x+d;x!==b.x;x+=d)out.push(`${x},${a.y}`)}return out}async function visualAttack(a,b,kind='melee',text=''){battleAnimating=true;let ak=`${a.x},${a.y}`,bk=`${b.x},${b.y}`;if(kind==='projectile'){let cells=lineCells(a,b);for(let k of [...cells,bk]){B.fx={projectileAt:k,projectile:'➶'};renderBattle();await sleep(90)}}else if(kind==='poison'){B.fx={projectileAt:bk,projectile:'☠️'};renderBattle();await sleep(180);let [x,y]=[b.x,b.y];B.fx={kind:'poison',cells:[[x,y],[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&b>=0&&a<10&&b<10).map(q=>q.join(','))};renderBattle();await sleep(260)}else if(kind==='shield'){B.fx={target:ak,floatAt:ak,floatText:text||'+🛡️'};renderBattle();await sleep(260)}else{B.fx={attacker:ak,target:bk};renderBattle();await sleep(130)}if(text&&kind!=='shield'){B.fx={target:bk,floatAt:bk,floatText:text};renderBattle();await sleep(260)}B.fx=null;battleAnimating=false;renderBattle()}
async function animateBattlePath(u,path,steps=path.length-1,delay=170,checkAoO=false){battleAnimating=true;for(let i=1;i<=steps&&i<path.length;i++){let old={x:u.x,y:u.y};u.x=path[i][0];u.y=path[i][1];faceStep(u,old);if(checkAoO)enemyAoO(old,u);renderBattle();await new Promise(r=>setTimeout(r,delay));if(!u.alive)break}battleAnimating=false}async function battleTap(e){let tile=e.target.closest('.tile');if(!tile||cur().type!=='hero'||battleAnimating)return;let x=+tile.dataset.x,y=+tile.dataset.y,h=getU('hero'),tapped=occupied(x,y);if(!B.selectedAction){if(tapped?.alive){B.selectedUnitId=tapped.id;renderBattle()}return}if(B.selectedAction==='move'){let stepCost=B.carryingBody?2:1,reach=reachable(h,Math.floor(h.pm/stepCost));if(!reach.has(`${x},${y}`))return;let path=gridPath(h,{x,y});if(!path.length)return;let steps=path.length-1,cost=steps*stepCost;h.pm-=cost;await animateBattlePath(h,path,cost,170,true);B.log.push(`⚔️ se mueve ${steps} casilla${steps!==1?'s':''}${B.carryingBody?' cargando un cuerpo':''}.`);renderBattle();if(checkBattleEnd())return;return}if(B.selectedAction==='movebody'){let z=occupied(x,y);if(!B.carryingBody){if(!z||z.alive||!adj8(h,z)||h.pa<1)return;h.pa--;B.carryingBody=z.id;z.x=-99;z.y=-99;B.log.push(`☠️ ${h.name} levanta un cuerpo.`);renderBattle();return}let c=getU(B.carryingBody);if(!free(x,y)||!adj8(h,{x,y}))return;c.x=x;c.y=y;B.log.push(`☠️ ${h.name} suelta el cuerpo.`);B.carryingBody=null;renderBattle();return}if(B.selectedAction==='block'){if(x!==h.x||y!==h.y)return;if(h.pa<1||(h.uses.block||0)>=2)return toast('No podés usar Bloqueo.');h.pa--;h.shield+=3;h.uses.block=(h.uses.block||0)+1;B.log.push('⚔️ Bloqueo: +3 Escudo.');await visualAttack(h,h,'shield','+3 🛡️');return}let z=occupied(x,y);if(!z||!validTargetTile(x,y,B.selectedAction))return;faceOrthogonalTarget(h,z);renderBattle();if(B.selectedAction==='normal'){h.pa--;let d=baseDamage(hero(),h.hp);await visualAttack(h,z,'melee',`-${d}`);hit(h,z,d,'Ataque Normal')}if(B.selectedAction==='power'){h.pa-=2;h.uses.power=1;let broken=Math.min(3,z.shield);z.shield-=broken;let d=baseDamage(hero(),h.hp)+2;await visualAttack(h,z,'melee',`-${d}`);hit(h,z,d,`Golpe Potenciado${broken?` (rompe ${broken} Escudo)`:''}`)}if(B.selectedAction==='cut'){h.pa-=2;h.uses.cut=(h.uses.cut||0)+1;let d=baseDamage(hero(),h.hp);await visualAttack(h,z,'melee',`-${d}`);hit(h,z,d,'Corte');if(z.alive)z.wound=(z.wound||0)+1}renderBattle();checkBattleEnd()}
function battleItems(){if(!B||cur()?.type!=='hero')return;let c=hero(),h=getU('hero'),items=c.inventory.map((n,i)=>itemData[n]?.use?`<button class="sell-row" data-combat-use="${i}">${esc(n)} <small>${itemData[n].effect}</small><b>1 PA</b></button>`:'').join('');modal(`<h3>🎒 Consumibles</h3><p>PA disponibles: <b>${h.pa}</b></p>${items||'<p>No tenés consumibles.</p>'}<p class="small">Usar un consumible en combate cuesta 1 PA.</p>`);document.querySelectorAll('[data-combat-use]').forEach(b=>b.onclick=()=>combatUseConsumable(+b.dataset.combatUse))}
function combatUseConsumable(i){let c=hero(),h=getU('hero'),name=c.inventory[i],d=itemData[name];if(!d?.use)return;if(h.pa<1)return toast('Necesitás 1 PA.');if(d.use==='heal'){if(h.hp>=h.max)return toast('Ya tenés la Vida completa.');h.hp=Math.min(h.max,h.hp+3)}else if(d.use==='antidote'){if(!h.poison)return toast('No tenés Veneno.');h.poison=0}else if(d.use==='bandage'){if(!h.wound)return toast('No tenés Herida.');h.wound=0}h.pa--;c.inventory.splice(i,1);save();closeModal();B.log.push(`🎒 ${name} utilizado (1 PA).`);renderBattle();toast(`${name} utilizado.`)}

function gridPath(a,b){let q=[[a.x,a.y]],prev=new Map([[`${a.x},${a.y}`,null]]);while(q.length){let [x,y]=q.shift();if(x===b.x&&y===b.y)break;for(let [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(nx<0||ny<0||nx>=10||ny>=10||obs.has(k)||prev.has(k)||(occupied(nx,ny)&&!(nx===b.x&&ny===b.y)))continue;prev.set(k,[x,y]);q.push([nx,ny])}}let k=`${b.x},${b.y}`;if(!prev.has(k))return[];let p=[b.x,b.y],out=[];while(p){out.push(p);p=prev.get(`${p[0]},${p[1]}`)}return out.reverse()}
function enemyAoO(old,h){for(let e of B.units.filter(z=>z.alive&&z.type!=='hero')){let was=Math.abs(e.x-old.x)+Math.abs(e.y-old.y)===1,now=Math.abs(e.x-h.x)+Math.abs(e.y-h.y)===1;if(was&&!now){let dmg=e.type==='dagger'?3:2;hit(e,h,dmg,'Ataque de Oportunidad')}}}
function hit(a,b,n,label){damage(b,n,true);B.log.push(`${a.icon} ${label}: ${n} daño a ${b.icon}.`)}function damage(u,n,useShield=true){if(useShield&&u.shield){let s=Math.min(u.shield,n);u.shield-=s;n-=s}u.hp-=n;if(u.hp<=0){u.hp=0;u.alive=false;B.log.push(`${u.icon} queda Fuera de Combate.`)}}
function clearLine(a,b){if(a.x!==b.x&&a.y!==b.y)return false;let dx=Math.sign(b.x-a.x),dy=Math.sign(b.y-a.y),x=a.x+dx,y=a.y+dy;while(x!==b.x||y!==b.y){if(obs.has(`${x},${y}`)||occupied(x,y))return false;x+=dx;y+=dy}return true}
async function enemyNotice(e,name){B.notice=`${e.icon} ${esc(e.name)} — <b>${name}</b>`;renderBattle();await new Promise(r=>setTimeout(r,520));B.notice=''}
async function enemyAI(){
 if(battleAnimating)return;if(!B||cur().type==='hero')return;
 let e=cur(),h=getU('hero');if(!h.alive)return nextTurn();
 // Jabalí: busca primero una Embestida alineada; si no, se acerca y usa Cornada/A.N.
 if(e.type==='boar'){
  // Movimiento normal primero. Si durante ese movimiento queda a alcance exacto 2 y alineado,
  // reserva la Embestida como desplazamiento extra de la habilidad (0 PM).
  if(h.alive&&!adj8(e,h)&&e.pm>0){let path=gridPath(e,h),maxSteps=Math.min(e.pm,Math.max(0,path.length-2)),steps=maxSteps;for(let i=1;i<=maxSteps;i++){let probe={x:path[i].x,y:path[i].y};if((probe.x===h.x||probe.y===h.y)&&md(probe,h)===2&&clearLine(probe,h)){steps=i;break}}if(steps>0){e.pm-=steps;await animateBattlePath(e,path,steps,190,false)}}
  // Alcance 2: Jabalí=0, casilla intermedia=1, objetivo=2. Solo línea recta ortogonal.
  if(h.alive&&e.pa>=1&&(e.x===h.x||e.y===h.y)&&md(e,h)===2&&clearLine(e,h)){
   faceTarget(e,h);renderBattle();await enemyNotice(e,'Embestida');let dx=Math.sign(h.x-e.x),dy=Math.sign(h.y-e.y),nx=e.x+dx,ny=e.y+dy;
   if(free(nx,ny)){e.pa--;await animateBattlePath(e,[[e.x,e.y],[nx,ny]],1,150,false);await sleep(140);if(adj8(e,h)){await visualAttack(e,h,'melee','-4');hit(e,h,4,'Embestida');renderBattle();await sleep(250)}}
  }
  if(h.alive&&!adj8(e,h)&&e.pm>0){let path=gridPath(e,h),steps=Math.min(e.pm,Math.max(0,path.length-2));if(steps>0){e.pm-=steps;await animateBattlePath(e,path,steps,190,false)}}
  if(h.alive&&adj8(e,h)&&e.pa>=2){faceTarget(e,h);renderBattle();await enemyNotice(e,'Cornada');e.pa-=2;e.uses.horn=1;await visualAttack(e,h,'melee','-2');hit(e,h,2,'Cornada');if(h.alive)h.wound=(h.wound||0)+1;renderBattle();await new Promise(r=>setTimeout(r,350))}
  while(h.alive&&adj8(e,h)&&e.pa>0){faceTarget(e,h);renderBattle();await enemyNotice(e,'Ataque Normal');e.pa--;await visualAttack(e,h,'melee','-2');hit(e,h,2,'Ataque Normal');renderBattle();await sleep(180)}
 }
 // Daga: Granada a distancia si puede; luego se acerca y usa Corte antes que A.N.
 if(e.type==='dagger'){
  if(e.pa>=2&&!adj8(e,h)&&md(e,h)<=2){faceTarget(e,h);renderBattle();await enemyNotice(e,'Granada Tóxica');e.pa-=2;e.uses.grenade=1;await visualAttack(e,h,'poison','');h.poison=(h.poison||0)+2;B.log.push('🗡️ Granada Tóxica: aplica Veneno 2.');renderBattle();await new Promise(r=>setTimeout(r,350))}
  if(h.alive&&!adj8(e,h)&&e.pm>0){let path=gridPath(e,h),steps=Math.min(e.pm,Math.max(0,path.length-2));if(steps>0){e.pm-=steps;await animateBattlePath(e,path,steps,190,false)}}
  if(h.alive&&adj8(e,h)&&e.pa>=2){faceTarget(e,h);renderBattle();await enemyNotice(e,'Corte');e.pa-=2;await visualAttack(e,h,'melee','-3');hit(e,h,3,'Corte');if(h.alive)h.wound=(h.wound||0)+1;renderBattle();await new Promise(r=>setTimeout(r,350))}
  while(h.alive&&adj8(e,h)&&e.pa>0){faceTarget(e,h);renderBattle();await enemyNotice(e,'Ataque Normal');e.pa--;await visualAttack(e,h,'melee','-3');hit(e,h,3,'Ataque Normal');renderBattle();await sleep(180)}
 }
 // Ballesta: busca línea de tiro; usa sus dos técnicas antes del ataque normal.
 if(e.type==='cross'){
  if(!(md(e,h)<=3&&clearLine(e,h))&&e.pm>0){let path=gridPath(e,h),steps=Math.min(e.pm,Math.max(0,path.length-4));if(steps>0){e.pm-=steps;await animateBattlePath(e,path,steps,190,false)}}
  if(h.alive&&md(e,h)<=3&&clearLine(e,h)&&e.pa>0){faceTarget(e,h);renderBattle();await enemyNotice(e,'Tiro Ralentizador');e.pa--;e.uses.slow=1;await visualAttack(e,h,'projectile','-2');damage(h,2,true);h.pm=Math.max(0,h.pm-1);B.log.push('🏹 Tiro Ralentizador: 2 daño y -1 PM.');renderBattle();await new Promise(r=>setTimeout(r,350))}
  if(h.alive&&md(e,h)<=3&&clearLine(e,h)&&e.pa>0){faceTarget(e,h);renderBattle();await enemyNotice(e,'Tiro Certero');e.pa--;e.uses.sure=1;await visualAttack(e,h,'projectile','-3');damage(h,3,false);B.log.push('🏹 Tiro Certero: 3 daño directo a Vida.');renderBattle();await new Promise(r=>setTimeout(r,350))}
  while(h.alive&&md(e,h)<=3&&clearLine(e,h)&&e.pa>0){faceTarget(e,h);renderBattle();await enemyNotice(e,'Ataque Normal');e.pa--;await visualAttack(e,h,'projectile','-2');hit(e,h,2,'Ataque Normal');renderBattle();await sleep(180)}
 }
 B.notice='';renderBattle();if(checkBattleEnd())return;setTimeout(nextTurn,650)
}
function checkBattleEnd(){let h=getU('hero'),enemies=B.units.filter(u=>u.type!=='hero');if(!h.alive){clearInterval(B.timerId);finishBattle(false);return true}if(enemies.every(e=>!e.alive)){clearInterval(B.timerId);finishBattle(true);return true}return false}
function finishBattle(win){let c=hero(),encounter=B.encounter,defeated=B.units.filter(u=>u.type!=='hero'&&!u.alive);let xp=defeated.length*2,gold=0,drops=[];for(let e of defeated){if(e.type==='boar'){gold+=rand(1,2);roll(.4,'Piel de jabalí');roll(.15,'Colmillo de jabalí')}if(e.type==='dagger'){gold+=rand(2,4);roll(.1,'Daga oxidada');roll(.15,'Botas de tela')}if(e.type==='cross'){gold+=rand(2,4);roll(.1,'Ballesta rota');roll(.15,'Botas de tela')}}function roll(p,item){if(Math.random()<p)drops.push(item)}c.xp+=xp;c.gold+=gold;drops.forEach(i=>addItem(c,i));if(win){c.hp=Math.max(1,getU('hero').hp);if(encounter==='boars'){c.location='west';if(side(c)==='hunt'&&countItem(c,'Piel de jabalí')>=5&&countItem(c,'Colmillo de jabalí')>=3)c.sideQuest='huntReady'}else{c.quest='done';c.location='outskirts'}}else{c.hp=1;c.location=c.startingPoint||'arca';c.worldPos.arca={x:355,y:270}}levelCheck(c);save();B=null;modal(`<h3>${win?'¡Victoria!':'Derrota'}</h3><p>EXP obtenida: <b>${xp}</b><br>Oro: <b>${gold}</b></p><div class="loot">${drops.length?drops.map(x=>'• '+x).join('<br>'):'Sin objetos adicionales.'}</div><p class="small">${win?(encounter==='boars'?'La manada fue derrotada. Podés seguir cazando o volver con el Guardia.':'Regresá con el Maestro de Arca para entregar la misión.'):'Conservás las recompensas de los enemigos derrotados. Volvés al Punto de Inicio con 1 Vida.'}</p><button id="continueWorld">Continuar</button>`,false);$('#continueWorld').onclick=()=>{closeModal();world()}}
function rand(a,b){return a+Math.floor(Math.random()*(b-a+1))}function addItem(c,item){if(c.inventory.length<12)c.inventory.push(item);else toast(`${item} se perdió: mochila llena.`)}function xpNeed(level){let n=10;for(let i=1;i<level;i++)n=Math.round(n*1.6);return n}function levelCheck(c){let gained=0;while(c.xp>=xpNeed(c.level)){c.xp-=xpNeed(c.level);c.level++;c.dev+=2;gained++}if(gained){c.hp=maxHp(c);setTimeout(()=>alert(`¡Nivel ${c.level}! Vida recuperada por completo. Obtienes ${gained*2} Puntos de Desarrollo.`),50)}}
